begin;
create extension if not exists pgtap with schema extensions;
select plan(28);
select is((select count(*)::integer from public.profiles),2,'two demo profiles');
select ok(not exists(select 1 from public.profiles where outreach_enabled or verified_at is not null),'fixtures cannot contact anyone');
select is(jsonb_array_length(public.list_escalation_candidates(20)),0,'disabled profiles absent from candidates');
set local role authenticated;
set local request.jwt.claim.sub='11111111-1111-4111-8111-111111111111';
select is((select count(*)::integer from public.profiles),1,'owner profile only');
select is((select count(*)::integer from public.reminders),2,'owner reminders only');
select is((select count(*)::integer from public.devices),1,'owner device only');
select is((select count(*)::integer from public.home_events),1,'owner event only');
select results_eq($$update public.reminders set title='Intrusion' where user_id='22222222-2222-4222-8222-222222222222' returning id$$,$$select null::uuid where false$$,'cross-owner update sees no rows');
select throws_ok($$insert into public.reminders(user_id,title,due_at) values('22222222-2222-4222-8222-222222222222','Intrusion',now())$$,'42501',null,'cross-owner insert rejected');
select throws_ok($$update public.profiles set verified_at=now()$$,'42501',null,'client cannot verify destination');
select throws_ok($$select public.list_escalation_candidates(20)$$,'42501',null,'candidate RPC server only');
select throws_ok($$select public.claim_escalation_attempt('{}')$$,'42501',null,'claim RPC server only');
select throws_ok($$select public.begin_notification_delivery(gen_random_uuid())$$,'42501',null,'delivery RPC server only');
select throws_ok($$insert into public.notification_attempts(user_id,revision,channel,stage,idempotency_key) values('11111111-1111-4111-8111-111111111111',1,'imessage','initial','forged')$$,'42501',null,'client cannot forge delivery history');
reset role;
update public.profiles set timezone='UTC',outreach_enabled=true,destination='simulation-only',verified_at=now(),opted_in_channels=array['imessage','facetime']::public.channel[];
update public.communication_rules set grace_seconds=0,high_call_seconds=0;
set local role service_role;
select is(jsonb_array_length(public.list_escalation_candidates(1)),1,'candidate list respects batch bound');
select is(jsonb_typeof(public.list_escalation_candidates(1)->0->'revision'),'string','candidate revision is a string');
select ok((public.list_escalation_candidates(1)->0->'policy') ? 'callsRemaining','candidate policy uses scheduler camelCase');
select isnt(public.claim_escalation_attempt('{"kind":"reminder","id":"aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1","revision":"1","channel":"imessage","stage":"initial"}'),null::jsonb,'eligible claim created');
select is(public.claim_escalation_attempt('{"kind":"reminder","id":"aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1","revision":"1","channel":"imessage","stage":"initial"}'),(select jsonb_build_object('attemptId',id) from public.notification_attempts where reminder_id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1'),'duplicate claim reuses attempt');
select is((select count(*)::integer from public.notification_attempts),1,'one attempt for same stage revision');
select is(public.claim_escalation_attempt('{"kind":"reminder","id":"aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1","revision":"1","channel":"facetime","stage":"escalation"}'),null::jsonb,'escalation waits for initial outcome');
update public.notification_attempts set status='simulated',outcome_at=now()-interval '1 minute';
select isnt(public.claim_escalation_attempt('{"kind":"reminder","id":"aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1","revision":"1","channel":"facetime","stage":"escalation"}'),null::jsonb,'distinct stage creates second attempt');
select isnt(public.begin_notification_delivery((select id from public.notification_attempts where stage='escalation')),null::jsonb,'transport gets send authorization once');
select is(public.begin_notification_delivery((select id from public.notification_attempts where stage='escalation')),null::jsonb,'second transport cannot send');
reset role;
update public.reminders set due_at=now()-interval '2 minutes' where id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1';
set local role service_role;
select is(public.claim_escalation_attempt('{"kind":"reminder","id":"aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1","revision":"1","channel":"imessage","stage":"initial"}'),null::jsonb,'stale revision rejected');
select isnt(public.claim_escalation_attempt('{"kind":"reminder","id":"aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1","revision":"2","channel":"imessage","stage":"initial"}'),null::jsonb,'new revision gets new attempt');
reset role;
update public.reminders set acknowledged_at=now() where id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1';
select is((select status::text from public.notification_attempts where revision=2),'canceled','ack cancels pending revision');
set local role service_role;
select is(public.begin_notification_delivery((select id from public.notification_attempts where revision=2)),null::jsonb,'stale queued delivery rejected');
select * from finish();
rollback;
